const input=$('Preparar entrada de correo').first().json;
if(!input.email_valid || !/^[A-Za-z0-9_.:-]{1,600}$/.test(input.Session_ID||'')) throw new Error('INVALID_MAIL_SESSION');
return [{json:{Session_ID:input.Session_ID,chatInput:input.chatInput,request_id:'WM3-M4-'+$execution.id}}];

const expected=$('Preparar sesión').first().json.Session_ID;
const rows=$input.all().map(x=>x.json).filter(x=>String(x.Session_ID||'')===expected);
if(rows.length>1)throw new Error('DUPLICATE_SESSION: hay más de una fila con el mismo Session_ID; Karla debe revisar antes de continuar.');
return [{json:rows[0]||{}}];

const session=$('Preparar sesión').first().json;
if (String($json.Session_ID)!==session.Session_ID) throw new Error('SESSION_MISMATCH');
let meta={}; try {meta=JSON.parse(String($json['Datos clave']||'{}'));} catch {}
return [{json:{...session,user_name:String($json['Nombre del usuario']||'No informado'),case_status:String($json['Estado del caso']||'En recepción'),last_summary:String($json['Resumen consolidado']||'Aún no hay un resumen consolidado.'),datos_clave:meta.facts||{},message_count:Number.isInteger(meta.message_count)?meta.message_count:0,messages_since_summary:Number.isInteger(meta.messages_since_summary)?meta.messages_since_summary:0}}];

const items=$input.all().map(x=>x.json);
const messages=items.flatMap(x=>Array.isArray(x.messages)?x.messages:[x]).slice(-12);
const state=$('Integrar resultado').first().json;
return [{json:{summary_input:{session_id:state.Session_ID,resumen_anterior:state.last_summary,datos_confirmados:state.datos_clave,historial_reciente:messages}}}];

const raw=String($json.text||$json.output||'').trim().replace(/^```(?:json)?\s*/i,'').replace(/\s*```$/,'');
const r=JSON.parse(raw);
if (Object.keys(r).sort().join(',')!=='accion_requerida,asunto_principal,puntos_clave') throw new Error('Claves de resumen inválidas');
if(typeof r.asunto_principal!=='string'||typeof r.accion_requerida!=='string'||!Array.isArray(r.puntos_clave)||r.puntos_clave.some(x=>typeof x!=='string'))throw new Error('Tipos de resumen inválidos');
r.asunto_principal=r.asunto_principal.slice(0,300);r.puntos_clave=r.puntos_clave.slice(0,8).map(x=>x.slice(0,240));r.accion_requerida=r.accion_requerida.slice(0,500);
return [{json:{summary_json:r,was_summarized:true}}];

